### What problem does this feature solve?

I followed the tutorial:product detail in the Doc and wrote some code. I did not encapsulate the hook as in the Demo, but as follows:
```TSX
export default function () {
    const touchStartXRef = useMainThreadRef<number>(0)
    const touchStartOffsetRef = useMainThreadRef<number>(0)
    const currentOffsetRef = useMainThreadRef<number>(0)

    const containerRef = useMainThreadRef<MainThread.Element>(null)

    function handleTouchStart(e: MainThread.TouchEvent) {
        'main thread'
        touchStartXRef.current = e.touches[0].clientX
        touchStartOffsetRef.current = currentOffsetRef.current
    }

    function handleTouchMove(e: MainThread.TouchEvent) {
        'main thread'
        const delta = e.touches[0].clientX - touchStartXRef.current
        const offset = touchStartOffsetRef.current + delta
        updateOffset(offset)
    }

    function updateOffset(offset: number) {
        'main thread'
        currentOffsetRef.current = offset

        containerRef.current?.setStyleProperties({
            transform: `translateX(${offset}px)`
        })
    }

    return (
        <view className='swiper-wrapper'>
            <view
                className='swiper-container'
                main-thread:ref={containerRef}
                main-thread:bindtouchstart={handleTouchStart}
                main-thread:bindtouchmove={handleTouchMove}
            >
                {logoList.map((logo, i) => {
                    return <image key={i} src={logo.src} className={logo.class} />
                })}
            </view>
        </view>
    )
}
```
But I got an error: main-thread.js exception: lexical variable is not initialized.

Then I made the following adjustments：
```tsx
export default function () {
    // ...

+   function handleTouchMove(e: MainThread.TouchEvent, updater:any) {
        'main thread'
        const delta = e.touches[0].clientX - touchStartXRef.current
        const offset = touchStartOffsetRef.current + delta
+     updater(offset)
    }

    function updateOffset(offset: number) {
        'main thread'
        currentOffsetRef.current = offset

        containerRef.current?.setStyleProperties({
            transform: `translateX(${offset}px)`
        })
    }

    return (
        <view className='swiper-wrapper'>
            <view
                className='swiper-container'
                main-thread:ref={containerRef}
                main-thread:bindtouchstart={handleTouchStart}
+                main-thread:bindtouchmove={(e)=>{
+                    'main thread'
+                    handleTouchMove(e,updateOffset)
+                }}
            >
                {logoList.map((logo, i) => {
                    return <image key={i} src={logo.src} className={logo.class} />
                })}
            </view>
        </view>
    )
}
```

I think this is very troublesome. I guess the problem is that the function is not analyzed during static analysis.

Is it possible to provide a withMainThread API to help static analysis?

### What does the proposed API of configuration look like?

```tsx
export default function () {
    // ...

   function handleTouchMove(e: MainThread.TouchEvent) {
        'main thread'
        const delta = e.touches[0].clientX - touchStartXRef.current
        const offset = touchStartOffsetRef.current + delta
        updateOffset(offset)
    }

+    const updateOffset = withMainThread( (offset: number) =>{
        'main thread'
        currentOffsetRef.current = offset

        containerRef.current?.setStyleProperties({
            transform: `translateX(${offset}px)`
        })
    })

    return (
        <view className='swiper-wrapper'>
            <view
                className='swiper-container'
                main-thread:ref={containerRef}
                main-thread:bindtouchstart={handleTouchStart}
                main-thread:bindtouchmove={handleTouchMove}
            >
                {logoList.map((logo, i) => {
                    return <image key={i} src={logo.src} className={logo.class} />
                })}
            </view>
        </view>
    )
}
```

or 
```tsx
   function handleTouchMove(e: MainThread.TouchEvent) {
        'main thread'
        const delta = e.touches[0].clientX - touchStartXRef.current
        const offset = touchStartOffsetRef.current + delta
+        withMainThread(updateOffset).invoke(offset)
    }
```

